def process(boston_harbor_beaches_list, wollaston_beach_list):
    bh_beaches = boston_harbor_beaches_list['Beach Name'].unique()
    ws_beaches = ['Milton Road', 'Channing Street', 'Sachem Street', 'Rice Road']

    result_list = []
    result_list.append('Boston Harbor beaches in high EJ communities:')
    for b in sorted(bh_beaches):
        result_list.append(f'  {b}')

    result_list.append('\nWollaston Beach locations:')
    for b in ws_beaches:
        result_list.append(f'  {b}')

    result_list.append('\nOverlap: None - these are different datasets')

    return pd.DataFrame({'note': result_list})

def process(wollaston_beach_list):
    df = wollaston_beach_list.copy()
    df['date'] = pd.to_datetime(df['date'])

    results = []
    for _, row in df.iterrows():
        rain_3day = row['rain_3day']
        date = row['date']

        for location in ['milton', 'channing', 'sachem', 'rice']:
            entero_raw = row[f'{location}_entero']
            tag = row[f'{location}_tag']

            if pd.isna(entero_raw) or entero_raw == '':
                continue

            try:
                entero_val = float(entero_raw)

                if pd.notna(tag):
                    if tag == '<':
                        entero_val = entero_val / 2.0
                    elif tag == '>':
                        pass

                if pd.notna(rain_3day):
                    results.append({
                        'date': date,
                        'location': location,
                        'rain_3day': rain_3day,
                        'entero_value': entero_val
                    })
            except (ValueError, TypeError):
                pass

    return pd.DataFrame(results)
